class Solution {
    public String crackCipher(String plain, String coded, String message) {
        boolean[] seenC = new boolean[26], seenP = new boolean[26];
        int known = 0;
        for (int i = 0; i < coded.length(); i++) {
            char c = coded.charAt(i);
            if (c == ' ') continue;
            if (!seenC[c - 'a']) { seenC[c - 'a'] = true; known++; }
            seenP[plain.charAt(i) - 'a'] = true;
        }
        char spareC = 0, spareP = 0;
        if (known == 25)
            for (int x = 0; x < 26; x++) { if (!seenC[x]) spareC = (char) ('a' + x); if (!seenP[x]) spareP = (char) ('a' + x); }
        StringBuilder out = new StringBuilder();
        for (char c : message.toCharArray()) {
            int at = coded.indexOf(c);
            if (c == ' ') out.append(' ');
            else if (at >= 0) out.append(plain.charAt(at));
            else out.append(c == spareC ? spareP : '?');
        }
        return out.toString();
    }
}

