            if (back[c - 'a'] == 0) known++;
            back[c - 'a'] = plain.charAt(i);
            used[plain.charAt(i) - 'a'] = true;
        }
        if (known == 25) {
            int spare = 0;
            while (used[spare]) spare++;
            for (int x = 0; x < 26; x++) if (back[x] == 0) back[x] = (char) ('a' + spare);
